/* Read-only verification against real facts generated by the local timing E2E. */
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const assert = require('node:assert/strict');
const report = JSON.parse(fs.readFileSync(process.env.E2E_TIMING_REPORT || '/tmp/gateway-observability-session-timing-e2e.json'));
const review = JSON.parse(fs.readFileSync(process.env.E2E_TIMING_REVIEW || '/tmp/gateway-observability-session-timing-review.json'));
const output = process.env.E2E_SCREENSHOT_DIR || '/tmp/session-timing-screenshots';
const base = process.env.E2E_BASE_URL || 'https://127.0.0.1:18443';
const localDate = value => new Date(new Date(value).getTime() + 8 * 3600000).toISOString().slice(0, 19);
const groups = value => value.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const duration = value => {
  const padded = value.padStart(4, '0');
  return `${groups(padded.slice(0, -3))}.${padded.slice(-3)} ms（${groups(value)} µs）`;
};
(async () => {
  fs.mkdirSync(output, { recursive: true });
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  try {
    const context = await browser.newContext({ ignoreHTTPSErrors: true, viewport: { width: 1680, height: 1200 }, locale: 'zh-CN', timezoneId: 'Asia/Shanghai' });
    const response = await context.request.post(base + '/admin/login', { data: {
      username: process.env.E2E_ADMIN_USER || 'congcong', password: process.env.E2E_ADMIN_PASSWORD || 'congcong',
    } });
    assert(response.ok(), 'Login failed');
    const { token } = await response.json();
    await context.addInitScript(value => localStorage.setItem('token', value), token);
    const page = await context.newPage();
    const errors = [];
    page.on('pageerror', error => errors.push(error.message));
    await page.goto(base + '/config');
    await page.getByRole('menuitem').filter({ hasText: '新版日志审计' }).click();
    await page.getByRole('heading', { name: '新版日志审计' }).waitFor();
    await page.locator('.ant-table-row').first().waitFor();
    async function filter(from, to, username, target = '') {
      await page.getByLabel('开始时间', { exact: true }).fill(localDate(from));
      await page.getByLabel('结束时间', { exact: true }).fill(localDate(to));
      await page.getByRole('textbox', { name: '用户', exact: true }).fill(username);
      await page.getByRole('textbox', { name: '目标／域名', exact: true }).fill(target);
      const requested = page.waitForResponse(r => r.url().includes('/sessions/page?') && r.status() === 200);
      await page.getByRole('button', { name: /查\s*询/ }).click();
      const list = await (await requested).json();
      await page.locator('.ant-table-row').first().waitFor();
      return list;
    }
    const list = await filter(report.from, report.to, 'home-01-timing-e2e');
    assert.equal(Number(list.total), report.counts.sessions);
    await page.screenshot({ path: path.join(output, 'timing-sessions.png'), fullPage: true });
    const screenshots = [];
    async function inspect(sample, name) {
      const row = page.locator(`.ant-table-row[data-row-key="${sample.recordId}"]`);
      const loading = page.waitForResponse(r => r.url().includes('/sessions/' + sample.recordId + '?') && r.status() === 200);
      await row.getByRole('button', { name: /查\s*看/ }).click();
      const detail = await (await loading).json();
      const dialog = page.getByRole('dialog');
      const times = dialog.locator('.ant-card').filter({ has: page.getByText('时间与耗时', { exact: true }) });
      await times.waitFor();
      for (const field of ['clientHandshakeDurationUs', 'targetRecoveryDurationUs', 'routeSelectionDurationUs', 'dnsDurationUs',
        'outboundTcpDurationUs', 'outboundTlsDurationUs', 'proxyHandshakeDurationUs', 'uploadBackpressureDurationUs', 'downloadBackpressureDurationUs']) {
        assert.equal(detail[field], sample[field], `${name}: ${field} differs from the audited fact`);
        if (detail[field] != null) assert(await times.getByText(duration(detail[field]), { exact: true }).count() > 0, `${name}: measured ${field} absent from UI`);
      }
      assert.equal(await dialog.getByText('限流等待', { exact: true }).count(), 0);
      if (sample.outboundProtocol === 'VLESS_REALITY') assert(await dialog.getByText('本地请求已发送', { exact: true }).count() > 0);
      if (sample.inboundProtocol === 'TLS_SNI_TCP') assert(await times.getByText('不适用（见目标恢复耗时）', { exact: true }).count() > 0);
      if (sample.connectOutcome === 'FAILED') assert(await times.getByText('未进入中继', { exact: true }).count() > 0);
      await times.scrollIntoViewIfNeeded();
      const file = 'timing-' + name + '.png';
      await times.screenshot({ path: path.join(output, file) });
      screenshots.push(file);
      await dialog.locator('.ant-drawer-close').click();
      await dialog.waitFor({ state: 'hidden' });
    }
    for (const [host, name] of [['reality.timing.home-proxy.test', 'reality'], ['http.timing.home-proxy.test', 'http'],
      ['download.timing.home-proxy.test', 'download-backpressure'], ['upload.timing.home-proxy.test', 'upload-backpressure'],
      ['reject.timing.home-proxy.test', 'upstream-failure'], ['localhost', 'sni-recovery']]) {
      await inspect(report.sessionSamples.find(row => row.logicalTargetHost === host), name);
    }
    const transparent = review.samples.find(row => row.inboundProtocol === 'TP_PROXY' && row.logicalTargetPort === 29290);
    await filter(review.scope.from, review.scope.to, '', transparent.logicalTargetHost);
    await inspect(transparent, 'fake-ip-dns');
    assert.equal(errors.length, 0, errors.join('; '));
    const result = { output, realSessionDetailsVerified: screenshots.length, filteredSessionCount: Number(list.total),
      browserErrors: errors, valuesMatchAuditedFacts: true, removedLimiterField: true, protocolApplicability: true, screenshots };
    fs.writeFileSync(path.join(output, 'browser-review.json'), JSON.stringify(result, null, 2));
    console.log(JSON.stringify(result, null, 2));
  } finally { await browser.close(); }
})().catch(error => { console.error(error); process.exit(1); });
